from pathlib import Path
import re
path = Path("HTMLparser.c")
s = path.read_text(encoding="utf-8", errors="surrogateescape")

# Replace htmlSkipBlankChars implementation with a bounds-checked variant.
pat = re.compile(r"static int\nhtmlSkipBlankChars\(xmlParserCtxtPtr ctxt\) \{[\s\S]*?\n\}", re.M)
m = pat.search(s)
if not m:
    raise SystemExit("htmlSkipBlankChars not found")
old = m.group(0)

new = """static int
htmlSkipBlankChars(xmlParserCtxtPtr ctxt) {
    int res = 0;

    if ((ctxt == NULL) || (ctxt->input == NULL) ||
        (ctxt->input->cur == NULL) || (ctxt->input->end == NULL))
        return(0);

    while ((ctxt->input->cur < ctxt->input->end) &&
           (IS_BLANK_CH(*ctxt->input->cur))) {
        if (*ctxt->input->cur == '\n') {
            ctxt->input->line++;
            ctxt->input->col = 1;
        } else {
            ctxt->input->col++;
        }
        ctxt->input->cur++;

        /* Grow input safely if we reached the end of the current buffer. */
        if (ctxt->input->cur >= ctxt->input->end) {
            xmlParserGrow(ctxt);
            if ((ctxt->input->cur == NULL) || (ctxt->input->end == NULL) ||
                (ctxt->input->cur >= ctxt->input->end))
                break;
        } else if (*ctxt->input->cur == 0) {
            xmlParserGrow(ctxt);
            if ((ctxt->input->cur == NULL) || (ctxt->input->end == NULL) ||
                (ctxt->input->cur >= ctxt->input->end))
                break;
        }

        if (res < INT_MAX)
            res++;
    }
    return(res);
}"""

s = s[:m.start()] + new + s[m.end():]
path.write_text(s, encoding="utf-8", errors="surrogateescape")
print("patched htmlSkipBlankChars")
